  tb.resize(428,84);
  tb.fills = S(C.surface);
  const items=[["Home","1:244"],["Explore","1:237"],["Library","1:245"]];
  for(let i=0;i<items.length;i++){
    const [label,id]=items[i];
    const active = label===current;
    const col = active? C.brand : C.textSec;
    const ic = await icon(id,24,col);
    ic.x = 60+i*154; ic.y=14; tb.appendChild(ic);
