function findFrame(name){ return page.children.find(f => f.name === name); }
function listAll(frame){
  let out=[];
  function rec(n,d){
    out.push("  ".repeat(d)+n.name+" "+n.id);
    if(n.children) for(const c of n.children) rec(c,d+1);
  }
  rec(frame,0);
  return out.join("\n");
}
throw new Error(listAll(findFrame("06_Library")));

